#!/usr/bin/env bash
set -Euo pipefail

VERSION="1.2.1"
ENGINE_VERSION="1.2.0"
ENGINE_SHA_AMD64="d694852767391132bd7b51dc7ddcbd028efc5e8d859a6efed5aa777772130041"
ENGINE_SHA_ARM64="bb0228b4a89f4caba9be97fb0fcacd196691a5f6de4a8b5569f7e5fccadce4ad"
SERVICE="superflash-xhttp.service"
BASE="/etc/superflash-xhttp"
TLS_DIR="$BASE/tls"
CONFIG="$BASE/config"
BIN="/usr/local/bin/superflash-xhttp-server"
RUNNER="/usr/local/sbin/superflash-xhttp-run"
UNIT="/etc/systemd/system/$SERVICE"
ACME="/root/.acme.sh/acme.sh"
DEFAULT_XHTTP_PORT=443
DEFAULT_SSH_PORT=22

B64_AMD64=''
B64_ARM64=''

red='\033[1;31m'; green='\033[1;32m'; cyan='\033[1;36m'; yellow='\033[1;33m'; reset='\033[0m'

need_root(){ if [ "${EUID:-$(id -u)}" -ne 0 ]; then echo -e "${red}Ejecuta como root.${reset}"; exit 1; fi; }
pause(){ echo; read -r -p "Presiona ENTER para continuar..." _ || true; }
valid_port(){ [[ "${1:-}" =~ ^[0-9]+$ ]] && [ "$1" -ge 1 ] && [ "$1" -le 65535 ]; }
valid_domain(){ [[ "${1:-}" =~ ^([A-Za-z0-9]([A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)+[A-Za-z]{2,63}$ ]]; }

expected_engine_sha(){
  case "$(uname -m)" in
    x86_64|amd64) echo "$ENGINE_SHA_AMD64" ;;
    aarch64|arm64) echo "$ENGINE_SHA_ARM64" ;;
    *) echo "" ;;
  esac
}
engine_hash(){
  [ -f "$BIN" ] && sha256sum "$BIN" 2>/dev/null | awk '{print $1}' || true
}
engine_state(){
  local exp got
  exp="$(expected_engine_sha)"; got="$(engine_hash)"
  if [ -z "$got" ]; then
    echo "NO INSTALADO"
  elif [ -n "$exp" ] && [ "$got" = "$exp" ]; then
    echo "ACTUAL v$ENGINE_VERSION"
  else
    echo "ANTIGUO/OTRO"
  fi
}

load_config(){
  XHTTP_PORT="$DEFAULT_XHTTP_PORT"; SSH_PORT="$DEFAULT_SSH_PORT"; DOMAIN=""; ACME_EMAIL=""
  if [ -f "$CONFIG" ]; then
    # shellcheck disable=SC1090
    . "$CONFIG"
  fi
}

save_config(){
  mkdir -p "$BASE" "$TLS_DIR"
  cat > "$CONFIG" <<EOF
XHTTP_PORT=$XHTTP_PORT
SSH_PORT=$SSH_PORT
DOMAIN=$DOMAIN
ACME_EMAIL=$ACME_EMAIL
EOF
  chmod 600 "$CONFIG"
}

install_deps(){
  if command -v apt-get >/dev/null 2>&1; then
    DEBIAN_FRONTEND=noninteractive apt-get update -y >/dev/null
    DEBIAN_FRONTEND=noninteractive apt-get install -y curl ca-certificates openssl socat >/dev/null
  elif command -v dnf >/dev/null 2>&1; then
    dnf install -y curl ca-certificates openssl socat >/dev/null
  elif command -v yum >/dev/null 2>&1; then
    yum install -y curl ca-certificates openssl socat >/dev/null
  else
    for c in curl openssl socat; do command -v "$c" >/dev/null 2>&1 || { echo "Falta $c"; return 1; }; done
  fi
}

install_engine(){
  install_deps || return 1
  local arch data expected tmp_hash was_active=0
  systemctl is-active --quiet "$SERVICE" 2>/dev/null && was_active=1 || true
  arch="$(uname -m)"
  case "$arch" in
    x86_64|amd64) data="$B64_AMD64"; expected="$ENGINE_SHA_AMD64" ;;
    aarch64|arm64) data="$B64_ARM64"; expected="$ENGINE_SHA_ARM64" ;;
    *) echo -e "${red}Arquitectura no soportada: $arch${reset}"; return 1 ;;
  esac
  mkdir -p "$BASE" "$TLS_DIR"
  echo "$data" | base64 -d | gzip -d > "$BIN.tmp"
  tmp_hash="$(sha256sum "$BIN.tmp" | awk '{print $1}')"
  if [ "$tmp_hash" != "$expected" ]; then
    rm -f "$BIN.tmp"
    echo -e "${red}Fallo de integridad del motor XHTTP: SHA-256 no coincide.${reset}"
    return 1
  fi
  chmod 0755 "$BIN.tmp"
  mv -f "$BIN.tmp" "$BIN"

  cat > "$RUNNER" <<'EOF'
#!/usr/bin/env bash
set -Eeuo pipefail
. /etc/superflash-xhttp/config
exec /usr/local/bin/superflash-xhttp-server \
  -listen "0.0.0.0:${XHTTP_PORT}" \
  -backend "127.0.0.1:${SSH_PORT}" \
  -cert /etc/superflash-xhttp/tls/fullchain.pem \
  -key /etc/superflash-xhttp/tls/key.pem
EOF
  chmod 0755 "$RUNNER"

  cat > "$UNIT" <<EOF
[Unit]
Description=SuperFlash XHTTP TLS/HTTP2 SSH transport v${ENGINE_VERSION}
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
ExecStart=$RUNNER
Restart=on-failure
RestartSec=2
LimitNOFILE=65536
NoNewPrivileges=true
PrivateTmp=true
ProtectHome=true
ProtectSystem=full

[Install]
WantedBy=multi-user.target
EOF
  systemctl daemon-reload
  systemctl enable "$SERVICE" >/dev/null 2>&1 || true
  load_config; save_config

  # FIX v1.2.1: reemplazar el archivo no cambia un proceso Go que ya estaba
  # ejecutándose. Si XHTTP estaba activo, reiniciarlo aquí para que el proceso
  # cargue realmente el motor 1.2.0 recién instalado.
  if [ "$was_active" -eq 1 ]; then
    if [ -s "$TLS_DIR/fullchain.pem" ] && [ -s "$TLS_DIR/key.pem" ]; then
      systemctl restart "$SERVICE"
      sleep .6
      if ! systemctl is-active --quiet "$SERVICE"; then
        echo -e "${red}El motor se instaló, pero XHTTP no pudo reiniciar.${reset}"
        journalctl -u "$SERVICE" -n 30 --no-pager || true
        return 1
      fi
      echo -e "${green}✔ Proceso XHTTP reiniciado con el motor nuevo.${reset}"
    else
      echo -e "${yellow}Motor actualizado; no se reinició porque falta certificado TLS.${reset}"
    fi
  fi

  echo -e "${green}✔ Motor SuperFlash XHTTP Server $ENGINE_VERSION instalado/actualizado.${reset}"
  echo "  SHA-256: $(engine_hash)"
  echo "  Estado  : $(engine_state)"
  echo "  BHTTP/puerto 80 NO fue modificado."
}

port_owner(){ ss -ltnp "sport = :$1" 2>/dev/null || true; }
ensure_443_free_for_acme(){
  systemctl stop "$SERVICE" >/dev/null 2>&1 || true
  sleep .3
  if ss -ltn "sport = :443" 2>/dev/null | grep -q LISTEN; then
    echo -e "${red}El puerto 443 está ocupado por otro servicio:${reset}"
    port_owner 443
    echo "Detén únicamente ese servicio y vuelve a emitir el certificado. No se toca BHTTP :80."
    return 1
  fi
}

install_acme(){
  [ -x "$ACME" ] && return 0
  install_deps
  if [ -n "${ACME_EMAIL:-}" ]; then
    curl -fsSL https://get.acme.sh | sh -s email="$ACME_EMAIL"
  else
    curl -fsSL https://get.acme.sh | sh
  fi
  [ -x "$ACME" ] || { echo -e "${red}No se pudo instalar acme.sh.${reset}"; return 1; }
}

configure_domain_cert(){
  install_engine || return 1
  load_config
  echo "Dominio actual: ${DOMAIN:-<sin configurar>}"
  read -r -p "Dominio XHTTP que apunta a esta VPS: " d
  d="${d,,}"
  valid_domain "$d" || { echo -e "${red}Dominio inválido.${reset}"; return 1; }
  read -r -p "Email Let's Encrypt (opcional) [${ACME_EMAIL:-}]: " e
  [ -n "$e" ] && ACME_EMAIL="$e"
  DOMAIN="$d"; save_config

  echo "DNS IPv4 observado para $DOMAIN:"
  getent ahostsv4 "$DOMAIN" 2>/dev/null | awk '{print $1}' | sort -u | sed -n '1,8p' || true
  echo -e "${yellow}El dominio debe llegar DIRECTAMENTE a esta VPS durante TLS-ALPN-01. Si usas CDN/proxy, ponlo temporalmente DNS-only para emitir/renovar.${reset}"
  ensure_443_free_for_acme || return 1
  install_acme || return 1
  mkdir -p "$TLS_DIR"

  "$ACME" --set-default-ca --server letsencrypt >/dev/null 2>&1 || true
  "$ACME" --issue --alpn -d "$DOMAIN" --server letsencrypt --keylength ec-256 \
    --pre-hook "systemctl stop $SERVICE >/dev/null 2>&1 || true" \
    --post-hook "systemctl start $SERVICE >/dev/null 2>&1 || true" \
    || { echo -e "${red}No se pudo emitir el certificado. Revisa DNS/puerto 443.${reset}"; return 1; }

  "$ACME" --install-cert -d "$DOMAIN" --ecc \
    --key-file "$TLS_DIR/key.pem" \
    --fullchain-file "$TLS_DIR/fullchain.pem" \
    --reloadcmd "systemctl restart $SERVICE >/dev/null 2>&1 || true"
  chmod 600 "$TLS_DIR/key.pem"
  chmod 644 "$TLS_DIR/fullchain.pem"
  echo -e "${green}✔ Certificado Let's Encrypt instalado para $DOMAIN.${reset}"
  echo "✔ TLS mínimo 1.2 + ALPN h2."
}

open_firewall(){
  local p="$1"
  if command -v ufw >/dev/null 2>&1; then
    ufw allow "${p}/tcp" >/dev/null 2>&1 || true
  fi
}

start_server(){
  load_config
  [ -x "$BIN" ] || install_engine || return 1
  [ -n "$DOMAIN" ] || { echo -e "${red}Primero configura dominio/certificado (opción 2).${reset}"; return 1; }
  [ -s "$TLS_DIR/fullchain.pem" ] && [ -s "$TLS_DIR/key.pem" ] || { echo -e "${red}Falta certificado TLS. Usa opción 2.${reset}"; return 1; }
  open_firewall "$XHTTP_PORT"
  systemctl restart "$SERVICE"
  sleep .5
  if systemctl is-active --quiet "$SERVICE"; then
    echo -e "${green}✔ XHTTP ON :$XHTTP_PORT -> SSH 127.0.0.1:$SSH_PORT${reset}"
  else
    echo -e "${red}XHTTP no inició. Últimos logs:${reset}"
    journalctl -u "$SERVICE" -n 30 --no-pager || true
    return 1
  fi
}

set_xhttp_port(){
  load_config; read -r -p "Puerto externo XHTTP [$XHTTP_PORT]: " p; p="${p:-$XHTTP_PORT}"
  valid_port "$p" || { echo "Puerto inválido"; return 1; }
  XHTTP_PORT="$p"; save_config; open_firewall "$p"; start_server
}

set_ssh_port(){
  load_config; read -r -p "Puerto SSH backend local [$SSH_PORT]: " p; p="${p:-$SSH_PORT}"
  valid_port "$p" || { echo "Puerto inválido"; return 1; }
  SSH_PORT="$p"; save_config
  systemctl restart "$SERVICE" >/dev/null 2>&1 || true
  echo -e "${green}✔ Backend configurado: 127.0.0.1:$SSH_PORT${reset}"
}

status_server(){
  load_config
  echo -e "${cyan}SUPERFLASH XHTTP — ESTADO${reset}"
  echo "Motor       : $(engine_state)"
  echo "Dominio     : ${DOMAIN:-<sin configurar>}"
  echo "XHTTP       : TCP ${XHTTP_PORT:-443}"
  echo "SSH backend : 127.0.0.1:${SSH_PORT:-22}"
  echo "Servicio    : $(systemctl is-active "$SERVICE" 2>/dev/null || echo inactive)"
  echo "BHTTP :80   : NO MODIFICADO por este manager"
  if [ -s "$TLS_DIR/fullchain.pem" ]; then
    echo "Certificado : $(openssl x509 -in "$TLS_DIR/fullchain.pem" -noout -subject 2>/dev/null | sed 's/^subject=//')"
    echo "Vence       : $(openssl x509 -in "$TLS_DIR/fullchain.pem" -noout -enddate 2>/dev/null | cut -d= -f2-)"
  else
    echo "Certificado : AUSENTE"
  fi
  echo
  echo "Listener XHTTP:"
  port_owner "${XHTTP_PORT:-443}"
  echo
  echo "SSH local:"
  ss -ltnp "sport = :${SSH_PORT:-22}" 2>/dev/null || true
}

self_test(){
  load_config
  systemctl is-active --quiet "$SERVICE" || { echo "XHTTP no está activo"; return 1; }
  [ -n "$DOMAIN" ] || { echo "Dominio no configurado"; return 1; }
  echo "1) Certificado / SNI:"
  openssl s_client -connect "127.0.0.1:${XHTTP_PORT}" -servername "$DOMAIN" -alpn h2 -brief </dev/null 2>&1 | sed -n '1,18p' || true
  echo
  echo "2) ALPN negociado:"
  local alpn
  alpn="$(echo | openssl s_client -connect "127.0.0.1:${XHTTP_PORT}" -servername "$DOMAIN" -alpn h2 2>/dev/null | tr -d '\000' | grep -a -E '^ALPN protocol:' | tail -1 || true)"
  echo "${alpn:-ALPN no visible}"
  if echo "$alpn" | grep -q 'h2'; then echo -e "${green}✔ TLS + ALPN h2 PASS${reset}"; else echo -e "${red}✘ No se confirmó h2${reset}"; fi
  if curl -V 2>/dev/null | grep -q HTTP2; then
    echo
    echo "3) Health HTTP/2 + stream-up:"
    local health_headers health_body
    health_headers="$(mktemp)"; health_body="$(mktemp)"
    if curl --http2 -fsS -D "$health_headers" -o "$health_body" \
        --resolve "$DOMAIN:${XHTTP_PORT}:127.0.0.1" \
        "https://$DOMAIN:${XHTTP_PORT}/xhttp/health"; then
      cat "$health_body"
      if grep -q 'SuperFlash XHTTP 1\.1\.0' "$health_body" 2>/dev/null; then
        echo -e "${red}✘ El proceso activo todavía es XHTTP 1.1.0 (motor viejo en memoria).${reset}"
        echo -e "${yellow}  Ejecuta opción 1; este manager v1.2.1 reiniciará automáticamente el servicio.${reset}"
      fi
      if tr -d '\r' < "$health_headers" | grep -qi '^x-http-upload-stream: 1$'; then
        echo -e "${green}✔ XHTTP STREAM-UP FAST PATH ACTIVO${reset}"
      else
        echo -e "${yellow}⚠ Health responde, pero stream-up no fue anunciado${reset}"
      fi
    fi
    rm -f "$health_headers" "$health_body"
  else
    echo "curl local no trae HTTP/2; la prueba ALPN anterior sigue siendo válida."
  fi
}

renew_cert(){
  load_config
  [ -n "$DOMAIN" ] || { echo "Dominio no configurado"; return 1; }
  install_acme || return 1
  ensure_443_free_for_acme || return 1
  "$ACME" --renew -d "$DOMAIN" --ecc --force
  "$ACME" --install-cert -d "$DOMAIN" --ecc \
    --key-file "$TLS_DIR/key.pem" --fullchain-file "$TLS_DIR/fullchain.pem" \
    --reloadcmd "systemctl restart $SERVICE >/dev/null 2>&1 || true"
  start_server
}

uninstall_server(){
  echo -e "${yellow}Esto elimina SOLO SuperFlash XHTTP. BHTTP y SSH no se tocan.${reset}"
  read -r -p "Escribe XHTTP para confirmar: " c
  [ "$c" = "XHTTP" ] || return 0
  systemctl disable --now "$SERVICE" >/dev/null 2>&1 || true
  rm -f "$UNIT" "$RUNNER" "$BIN"
  rm -rf "$BASE"
  systemctl daemon-reload
  echo -e "${green}✔ XHTTP desinstalado. BHTTP intacto.${reset}"
}

menu(){
  while true; do
    clear || true; load_config
    echo -e "${cyan}╔══════════════════════════════════════════════════════╗${reset}"
    echo -e "${cyan}║  SUPERFLASH XHTTP TLS/HTTP2 SERVER MANAGER v$VERSION     ║${reset}"
    echo -e "${cyan}╚══════════════════════════════════════════════════════╝${reset}"
    echo "Motor       : $(engine_state) (Go, sin token)"
    echo "Dominio     : ${DOMAIN:-<sin configurar>}"
    echo "XHTTP       : :${XHTTP_PORT:-443} -> SSH 127.0.0.1:${SSH_PORT:-22}"
    echo "Servicio    : $(systemctl is-active "$SERVICE" 2>/dev/null || true)"
    echo "BHTTP :80   : CONGELADO / NO SE TOCA"
    echo
    echo "1) Instalar/ACTUALIZAR motor XHTTP v$ENGINE_VERSION + REINICIO seguro"
    echo "2) Configurar dominio + certificado Let's Encrypt (TLS-ALPN-01)"
    echo "3) Abrir/iniciar XHTTP TCP 443"
    echo "4) Configurar puerto externo XHTTP"
    echo "5) Configurar puerto SSH backend (22 por defecto)"
    echo "6) Estado/diagnóstico"
    echo "7) Ver logs"
    echo "8) Autoprueba TLS + HTTP/2"
    echo "9) Renovar certificado ahora"
    echo "10) Reiniciar servidor XHTTP"
    echo "11) Detener servidor XHTTP"
    echo "12) Desinstalar SOLO XHTTP"
    echo "0) Salir"
    echo
    read -r -p "Opción: " op
    case "$op" in
      1) install_engine; pause;;
      2) configure_domain_cert; pause;;
      3) load_config; XHTTP_PORT=443; save_config; start_server; pause;;
      4) set_xhttp_port; pause;;
      5) set_ssh_port; pause;;
      6) status_server; pause;;
      7) journalctl -u "$SERVICE" -n 150 --no-pager || true; pause;;
      8) self_test; pause;;
      9) renew_cert; pause;;
      10) systemctl restart "$SERVICE"; sleep .5; status_server; pause;;
      11) systemctl stop "$SERVICE"; echo "XHTTP detenido. BHTTP intacto."; pause;;
      12) uninstall_server; pause;;
      0) exit 0;;
      *) echo "Opción inválida"; sleep 1;;
    esac
  done
}

need_root
menu
